// Ahorro.js
import React, { useState, useEffect, useCallback, useMemo } from 'react';
import './Ahorro.css';
import { Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend } from 'chart.js';
import { v4 as uuidv4 } from 'uuid';
import ObjetivosLista from './ObjetivosLista'; // Subcomponente para la lista de objetivos

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:5000';

const Ahorro = () => {
    const [objetivos, setObjetivos] = useState([]);
    const [nuevoObjetivo, setNuevoObjetivo] = useState({ nombre: '', monto: '', plazo: '' });
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(false);

    // Obtener objetivos de ahorro desde el backend al montar el componente
    useEffect(() => {
        const obtenerAhorro = async () => {
            try {
                const response = await fetch(`${API_BASE_URL}/api/Ahorro`, {
                    headers: {
                        'Content-Type': 'application/json',
                        // 'Authorization': `Bearer ${token}`, // Si aplica
                    },
                });
                if (response.ok) {
                    const data = await response.json();
                    setObjetivos(data);
                } else {
                    throw new Error('Error al obtener los Ahorro');
                }
            } catch (error) {
                setError(error.message);
            } finally {
                setLoading(false);
            }
        };

        obtenerAhorro();
    }, []);

    // Manejar cambios en el formulario
    const handleInputChange = useCallback((e) => {
        const { name, value } = e.target;
        setNuevoObjetivo((prev) => ({ ...prev, [name]: value }));
    }, []);

    // Validar el formulario antes de enviar
    const validateForm = useCallback(() => {
        const { nombre, monto, plazo } = nuevoObjetivo;
        if (!nombre.trim()) {
            setError('El nombre del objetivo es requerido.');
            return false;
        }
        if (!monto || monto <= 0) {
            setError('El monto debe ser un número positivo.');
            return false;
        }
        if (!plazo || plazo <= 0) {
            setError('El plazo debe ser un número positivo.');
            return false;
        }
        return true;
    }, [nuevoObjetivo]);

    // Agregar un nuevo objetivo de ahorro
    const agregarObjetivo = useCallback(async (e) => {
        e.preventDefault();
        setError(null);
        setSuccess(false);

        if (!validateForm()) return;

        try {
            const response = await fetch(`${API_BASE_URL}/api/Ahorro`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    // 'Authorization': `Bearer ${token}`, // Si aplica
                },
                body: JSON.stringify(nuevoObjetivo),
            });

            if (response.ok) {
                const objetivoCreado = await response.json();
                setObjetivos((prev) => [...prev, objetivoCreado]);
                setNuevoObjetivo({ nombre: '', monto: '', plazo: '' });
                setSuccess(true);
            } else {
                const errorData = await response.json();
                throw new Error(errorData.message || 'Error al agregar el objetivo de ahorro.');
            }
        } catch (error) {
            setError(error.message);
        }
    }, [nuevoObjetivo, validateForm]);

    // Datos para el gráfico
    const datosGrafico = useMemo(() => ({
        labels: objetivos.map(obj => obj.nombre),
        datasets: [
            {
                label: 'Monto Objetivo ($)',
                data: objetivos.map(obj => obj.monto),
                backgroundColor: 'rgba(75, 192, 192, 0.6)',
            },
        ],
    }), [objetivos]);

    const opcionesGrafico = useMemo(() => ({
        responsive: true,
        plugins: {
            legend: {
                position: 'top',
            },
            title: {
                display: true,
                text: 'Progreso de Objetivos de Ahorro',
            },
        },
    }), []);

    return (
        <div className="Ahorro-container">
            <h1 className="Ahorro-title">Ahorro</h1>
            <div className="Ahorro-content">
                {loading ? (
                    <p>Cargando...</p>
                ) : error ? (
                    <p className="error">{error}</p>
                ) : (
                    <>
                        <form onSubmit={agregarObjetivo} className="form-ahorro" noValidate>
                            <h2>Agregar Nuevo Objetivo de Ahorro</h2>
                            <div className="form-group">
                                <label htmlFor="nombre">Nombre del Objetivo:</label>
                                <input
                                    type="text"
                                    id="nombre"
                                    name="nombre"
                                    value={nuevoObjetivo.nombre}
                                    onChange={handleInputChange}
                                    required
                                />
                            </div>
                            <div className="form-group">
                                <label htmlFor="monto">Monto Objetivo ($):</label>
                                <input
                                    type="number"
                                    id="monto"
                                    name="monto"
                                    value={nuevoObjetivo.monto}
                                    onChange={handleInputChange}
                                    required
                                    min="0"
                                />
                            </div>
                            <div className="form-group">
                                <label htmlFor="plazo">Plazo (meses):</label>
                                <input
                                    type="number"
                                    id="plazo"
                                    name="plazo"
                                    value={nuevoObjetivo.plazo}
                                    onChange={handleInputChange}
                                    required
                                    min="1"
                                />
                            </div>
                            <button type="submit" className="btn-agregar" disabled={loading}>
                                {loading ? 'Agregando...' : 'Agregar Objetivo'}
                            </button>
                        </form>

                        {success && <p className="success">Objetivo agregado con éxito!</p>}

                        <div className="objetivos-lista">
                            <h2>Mis Objetivos de Ahorro</h2>
                            <ObjetivosLista objetivos={objetivos} />
                        </div>

                        {objetivos.length > 0 && (
                            <div className="grafico-Ahorro">
                                <Bar data={datosGrafico} options={opcionesGrafico} />
                            </div>
                        )}
                    </>
                )}
            </div>
        </div>
    );
};

export default Ahorro;
